INSERT INTO recipes (id, title, ingredients, instructions, notes, total_time, yield, archived, status, created_at, updated_at) VALUES ('c4rb0n4r', 'Spagetti carbonara', '[{"label":"","items":["400 g spagetti","150 g guanciale vagy pancetta","4 tojássárgája","1 egész tojás","80 g reszelt pecorino romano","Frissen őrölt fekete bors","Só a tésztavízbe"]}]', '["Bő, sós vízben kifőzzük a spagettit, a főzővízből félretesszük egy bögrényivel.","A felkockázott guanciale-t zsiradék nélkül, közepes lángon aranybarnára sütjük.","Egy tálban elkeverjük a tojásokat, a sajtot és bő borsot.","A leszűrt tésztát a serpenyőbe tesszük a tűzről levéve, ráöntjük a tojásos keveréket, és gyorsan átforgatjuk.","Ha túl sűrű, a félretett tésztavízzel hígítjuk, amíg selymes mártást kapunk. Azonnal tálaljuk."]', '[]', '0:25', '4 adag', 0, 'ready', '2025-09-14T18:20:00.000Z', '2025-09-14T18:20:00.000Z');
INSERT INTO recipe_tags (recipe_id, tag_id) VALUES ('c4rb0n4r', 'o7l2a9sz');
