INSERT INTO recipes (id, title, ingredients, instructions, notes, total_time, yield, archived, status, created_at, updated_at) VALUES ('t5h4a1cr', 'Thai zöldséges curry', '[{"label":"","items":["2 ek kókuszolaj","3 ek zöld curry paszta","1 doboz (400 ml) kókusztej","200 ml víz","1 cukkini","1 piros kaliforniai paprika","150 g brokkoli","1 kis csomag bébikukorica","1 ek szójaszósz","1 tk barna cukor","1 lime leve","Friss bazsalikom vagy koriander","Jázminrizs a tálaláshoz"]}]', '["A kókuszolajon 1-2 percig pirítjuk a curry pasztát, amíg illatos nem lesz.","Felöntjük a kókusztejjel és a vízzel, és felforraljuk.","Hozzáadjuk a felvágott zöldségeket, és 8-10 percig főzzük, hogy harapnivaló maradjon.","Szójaszósszal, cukorral és lime levével ízesítjük.","Jázminrizzsel tálaljuk, a tetejére friss fűszernövényt szórunk."]', '[]', '0:35', '4 adag', 0, 'ready', '2025-10-02T12:05:00.000Z', '2025-10-02T12:05:00.000Z');
