INSERT INTO recipes (id, title, ingredients, instructions, notes, total_time, yield, archived, status, created_at, updated_at) VALUES ('k0v4sz3k', 'Kovászos kenyér', '[{"label":"Tészta","items":["100 g aktív kovász","375 g víz","500 g fehér kenyérliszt","10 g só"]}]', '["Összekeverjük a kovászt a vízzel, hozzáadjuk a lisztet, és 30 percig pihentetjük.","Ráserkentjük a sót, átgyúrjuk, majd 4-5 órán át szobahőmérsékleten kelesztjük. Az első 2 órában félóránként hajtogatjuk.","Cipóvá formázzuk, kikent kosárba tesszük, és éjszakára hűtőbe rakjuk.","A sütőt edénnyel együtt 250 fokra előmelegítjük.","A cipót az edénybe tesszük, bevágjuk, 20 percig fedővel, majd 20-25 percig fedő nélkül sütjük.","Rácson teljesen kihűtjük, mielőtt felvágjuk."]', '[]', '18:00', '1 cipó', 0, 'development', '2025-10-19T07:40:00.000Z', '2025-10-19T07:40:00.000Z');
