INSERT INTO recipes (id, title, ingredients, instructions, notes, total_time, yield, archived, status, created_at, updated_at) VALUES ('b9r0wn1e', 'Csokis brownie', '[{"label":"","items":["150 g étcsokoládé","120 g vaj","200 g cukor","3 tojás","80 g liszt","30 g kakaópor","1 csipet só","100 g dió (elhagyható)"]}]', '["A csokoládét és a vajat gőz felett vagy mikróban felolvasztjuk, majd kicsit hűtjük.","A cukrot és a tojásokat 2-3 percig habosra keverjük, hozzáadjuk a csokoládés masszát.","Beleszitáljuk a lisztet, a kakaót és a sót, óvatosan átforgatjuk. Ha használunk diót, most keverjük bele.","Sütőpapírral bélelt, 20x20 cm-es formába simítjuk.","180 fokon 22-25 percig sütjük, a közepe maradjon kicsit nyirkos.","Teljesen kihűtjük, és csak utána szeleteljük."]', '[]', '0:50', '16 szelet', 0, 'ready', '2025-11-03T15:10:00.000Z', '2025-11-03T15:10:00.000Z');
