INSERT INTO recipes (id, title, ingredients, instructions, notes, total_time, yield, archived, status, created_at, updated_at) VALUES ('g0r0g5al', 'Görög saláta', '[{"label":"","items":["4 érett paradicsom","1 uborka","1 kis vöröshagyma","1 zöld paprika","100 g kalamata olajbogyó","200 g feta","4 ek olívaolaj","1 ek vörösborecet","1 tk szárított oregánó","Só"]}]', '["A paradicsomot cikkekre, az uborkát és a paprikát karikákra, a hagymát vékony félkarikákra vágjuk.","Egy tálban összeforgatjuk a zöldségeket az olajbogyóval.","Olívaolajjal és ecettel meglocsoljuk, enyhén sózzuk.","A tetejére tesszük a fetát egyben vagy nagy kockákban, és megszórjuk oregánóval."]', '[]', NULL, NULL, 0, 'development', '2025-11-10T11:30:00.000Z', '2025-11-10T11:30:00.000Z');
